css='''
.slide-inner{width:min(1240px,100%);margin:auto;padding:36px 56px;gap:22px}.slide-inner h1{font-size:clamp(30px,3.5vw,50px);line-height:1.15;max-width:100%}.slide-inner p,.slide-inner li{font-size:clamp(17px,1.6vw,23px)}.slide-inner li{margin:10px 0}.slide-inner .code{font-size:clamp(12px,1.15vw,17px);white-space:pre-wrap;overflow-wrap:anywhere}.deck-header{grid-template-columns:260px 1fr auto}.cp-rail button{font-size:14px}.deck-footer{position:fixed;bottom:0;left:0;right:0;height:56px;display:flex;align-items:center;justify-content:space-between;padding:0 28px;background:var(--surface);border-top:1px solid var(--rule)}button{padding:8px 14px;border:1px solid var(--rule);background:white;border-radius:6px}.active-cp{color:var(--signal);border-bottom:3px solid var(--signal)}#notes{display:none;position:fixed;right:0;top:76px;bottom:56px;width:390px;background:white;border-left:3px solid var(--signal);padding:28px;overflow:auto;z-index:30}#notes.open{display:block}.meter{height:3px;background:var(--signal);position:fixed;bottom:56px;left:0}.section-tag{color:var(--signal-ink);font-weight:700;letter-spacing:.08em}.data{font-size:20px}@media(max-width:800px){.deck-header{grid-template-columns:1fr auto}.cp-rail{display:none}.slide-inner{padding:24px}.grid-2{grid-template-columns:1fr}.data{font-size:16px}}@media print{.deck-header,.deck-footer,#notes,.meter{display:none!important}#deck{position:static}.slide{position:relative!important;display:flex!important;visibility:visible!important;opacity:1!important;min-height:100vh;break-after:page}.slide-inner{width:100%}@page{size:landscape;margin:10mm}}
'''
html='''<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lab 9 · Evaluation & Failure Analysis</title><link rel="stylesheet" href="theme.css"><style>'''+css+'''</style><link rel="stylesheet" href="enhance.css?v=schedule-20261117-1600-v3"></head><body><header class="deck-header"><div class="brand-text"><span class="brand-course">AI Thực Chiến · K5 Level 3</span><strong>Day 09 · 16:00–19:30</strong></div><nav class="cp-rail" aria-label="Checkpoint"></nav><div><button id="noteButton">Ghi chú N</button> <button id="full">Toàn màn hình F</button></div></header><main id="deck"></main><aside id="notes"></aside><div class="meter"></div><footer class="deck-footer"><span id="count"></span><span>← → chuyển slide · N ghi chú · F toàn màn hình</span><div><button id="prev">Trước</button> <button id="next">Tiếp</button></div></footer><script>const slides='''+json.dumps(slides,ensure_ascii=False)+''';
const esc=s=>s.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');let current=Math.max(0,Math.min(slides.length-1,Number(location.hash.slice(1)||1)-1));
document.querySelector('#deck').innerHTML=slides.map((s,i)=>`<section class="slide" aria-label="${s.title}"><div class="slide-inner"><div class="section-tag">${s.cp==='INTRO'?'PHẦN 1 · TỔNG QUAN':'PHẦN 2 · CHECKPOINT '+s.cp} / LAB 09</div><h1>${s.title}</h1>${s.body}${s.code?`<pre class="code">${esc(s.code)}</pre>`:''}</div></section>`).join('');
document.querySelector('.cp-rail').innerHTML=[...new Set(slides.map(s=>s.cp))].map(cp=>`<button data-cp="${cp}">${cp}</button>`).join('');
function show(n){current=Math.max(0,Math.min(slides.length-1,n));document.querySelectorAll('.slide').forEach((el,i)=>{el.style.display=i===current?'flex':'none';el.setAttribute('aria-hidden',i!==current)});document.querySelector('#count').textContent=`${current+1} / ${slides.length}`;document.querySelector('#notes').innerHTML=`<h2>Ghi chú giảng viên</h2><h3>${slides[current].title}</h3><p>${slides[current].note||(slides[current].cp==='INTRO'?'':'Đối chiếu với checkpoint tương ứng trong repo. Cho học viên giải thích bằng ví dụ của nhóm.')}</p>`;document.querySelectorAll('[data-cp]').forEach(b=>b.classList.toggle('active-cp',b.dataset.cp===slides[current].cp));document.querySelector('.meter').style.width=`${100*(current+1)/slides.length}%`;document.querySelector('#prev').disabled=current===0;document.querySelector('#next').disabled=current===slides.length-1;history.replaceState(null,'','#'+(current+1))}
document.querySelector('#next').onclick=()=>show(current+1);document.querySelector('#prev').onclick=()=>show(current-1);document.querySelector('#noteButton').onclick=()=>document.querySelector('#notes').classList.toggle('open');document.querySelector('#full').onclick=()=>document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen();document.querySelectorAll('[data-cp]').forEach(b=>b.onclick=()=>show(slides.findIndex(s=>s.cp===b.dataset.cp)));document.addEventListener('keydown',e=>{if(['ArrowRight','PageDown',' '].includes(e.key)){e.preventDefault();show(current+1)}if(['ArrowLeft','PageUp'].includes(e.key))show(current-1);if(e.key==='Home')show(0);if(e.key==='End')show(slides.length-1);if(e.key.toLowerCase()==='n')document.querySelector('#noteButton').click();if(e.key.toLowerCase()==='f')document.querySelector('#full').click()});show(current);</script><script src="enhance.js?v=schedule-20261117-1600-v3"></script><script src="courier.js"></script><script src="day9-scene.js?v=schedule-20261117-1600-v3"></script></body></html>'''
Path(__file__).with_name('index.html').write_text(html,encoding='utf-8')
